const rawOutput = $input.first().json.choices?.[0]?.message?.content || '{}';
const cleanJson = rawOutput.replace(/```json\n?|```/g, '').trim();

let classification = {};
let ia_fallback = false;
try {
  classification = JSON.parse(cleanJson);
} catch (e) {
  // CF-04: si la IA no devuelve un JSON parseable, no fabricamos una
  // clasificacion ni una confianza inventadas. Usamos un centinela
  // explicito y dejamos ia_fallback=true para poder filtrar estos
  // casos en vez de contarlos como aciertos/fallos de la IA.
  ia_fallback = true;
  classification = {
    clasificacion: 'sin_clasificar',
    prioridad: null,
    confianza: null,
    resumen: 'Fallo el parseo de la respuesta de IA (fallback CF-04).'
  };
}

const lead = $('⚙️ Normalización ETL + Enriquecimiento').item.json;

const ia_clasificacion = classification.clasificacion || 'sin_clasificar';
let ia_prioridad = ia_fallback ? null : (classification.prioridad ?? 50);
const ia_confianza = ia_fallback ? null : (classification.confianza ?? 0.5);

// Regla de negocio (m06): spam siempre prioridad 0, sin excepcion,
// incluso si el modelo devolvio otro valor.
if (ia_clasificacion === 'spam') {
  ia_prioridad = 0;
}

return [{
  json: {
    ...lead,
    ia_clasificacion,
    ia_prioridad,
    ia_confianza,
    ia_resumen: classification.resumen || '',
    ia_fallback,
    _stage: 'ia_clasificado'
  }
}];

