const rawOutput = $input.first().json.choices?.[0]?.message?.content || '{}';
const cleanJson = rawOutput.replace(/```json\n?|```/g, '').trim();
const lead = $('📊 Parsear: Extraer Clasificación IA').item.json;
let emailData = {};
try {
  emailData = JSON.parse(cleanJson);
} catch (e) {
  emailData = {
    asunto: 'Gracias por contactarnos, ' + (lead.nombre || '') + '!',
    cuerpo_html: '<p>Hola <strong>' + (lead.nombre || '') + '</strong>,</p><p>Gracias por tu consulta. Nuestro equipo la revisara y te contactara en las proximas 24 horas.</p><p>Saludos,<br>Equipo Comercial</p>'
  };
}
return [{
  json: {
    ...lead,
    ia_respuesta_asunto: emailData.asunto || '',
    ia_respuesta_html: emailData.cuerpo_html || '',
    _stage: 'ia_email_generado'
  }
}];

const lead = $input.first().json;
const motivo = lead.email_valido === false ? 'Email invalido' : 'Telefono insuficiente';

// En un entorno productivo, esto escribira en una tabla de errores de Supabase
// Por ahora, logueamos en consola y construimos un objeto de error estructurado
console.log(`[LEAD INVALIDO] ${motivo} - ${lead.email} - ${lead.nombre}`);

return [{
  json: {
    ...lead,
    estado: 'error_validacion',
    motivo_error: motivo,
    _stage: 'error_validacion'
  }
}];

